// Shared column builders and constraint helpers for the domain schema (docs/domain.md, section 0).
// Schema files import each other and this file by relative paths: drizzle-kit loads them without SvelteKit aliases.
import { sql, type SQL } from 'drizzle-orm';
import { check, customType, integer, text, timestamp, uuid, type AnyPgColumn } from 'drizzle-orm/pg-core';
import { uuidv7 } from '../../ids';

/** `id` — UUID v7 primary key generated by the application. */
export const id = () =>
	uuid()
		.primaryKey()
		.$defaultFn(() => uuidv7());

/** `ts` — a moment in time stored as `timestamptz`. */
export const ts = () => timestamp({ withTimezone: true, mode: 'date' });

/** `created_at` and `updated_at` of mutable records. */
export const timestamps = () => ({
	createdAt: ts().notNull().defaultNow(),
	updatedAt: ts()
		.notNull()
		.defaultNow()
		.$onUpdate(() => new Date())
});

/** `enc` — a value encrypted by the application (crypto/fields.ts). */
export const bytea = customType<{ data: Uint8Array; driverData: Buffer }>({
	dataType: () => 'bytea',
	toDriver: (value) => Buffer.from(value.buffer, value.byteOffset, value.byteLength),
	fromDriver: (value) => new Uint8Array(value.buffer, value.byteOffset, value.byteLength)
});

/**
 * pgvector column without a fixed dimension: the embedding space defines it (domain 16.3).
 * The driver exchanges vectors in the text form `[1,2,3]`.
 */
export const vector = customType<{ data: number[]; driverData: string }>({
	dataType: () => 'vector',
	toDriver: (value) => `[${value.join(',')}]`,
	fromDriver: (value) => value.slice(1, -1).split(',').map(Number)
});

function literal(value: string): SQL {
	return sql.raw(`'${value.replaceAll("'", "''")}'`);
}

/** `column IN ('a', 'b')` for `enum` columns (`text` + `CHECK`); `NULL` passes, nullability is a separate rule. */
export function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
	return sql`${column} in (${sql.join(values.map(literal), sql`, `)})`;
}

/** `column <@ ARRAY['a', 'b']` for `text[]` columns whose elements come from a fixed list. */
export function subsetOf(column: AnyPgColumn, values: readonly string[]): SQL {
	return sql`${column} <@ array[${sql.join(values.map(literal), sql`, `)}]::text[]`;
}

/** `CHECK` constraint for an `enum` column, named `{table}_{column}_values`. */
export function enumCheck(table: string, columnName: string, column: AnyPgColumn, values: readonly string[]) {
	return check(`${table}_${columnName}_values`, oneOf(column, values));
}

// --- Salary block (domain 0) ---

export const SALARY_PERIODS = ['month', 'year', 'hour', 'project'] as const;
export const SALARY_TAX_BASES = ['gross', 'net', 'unknown'] as const;

/** Salary columns shared by every table that stores a salary range. */
export const salaryColumns = () => ({
	salaryMin: integer(),
	salaryMax: integer(),
	salaryCurrency: text(),
	salaryPeriod: text({ enum: SALARY_PERIODS }),
	salaryTaxBase: text({ enum: SALARY_TAX_BASES })
});

interface SalaryColumns {
	salaryMin: AnyPgColumn;
	salaryMax: AnyPgColumn;
	salaryCurrency: AnyPgColumn;
	salaryPeriod: AnyPgColumn;
	salaryTaxBase: AnyPgColumn;
}

/**
 * Invariants of the salary block: bounds are non-negative and ordered; currency, period and tax base are present
 * as soon as any bound is known; currency is an ISO 4217 code.
 */
export function salaryChecks(table: string, t: SalaryColumns) {
	return [
		check(
			`${table}_salary_bounds`,
			sql`(${t.salaryMin} is null or ${t.salaryMin} >= 0) and (${t.salaryMax} is null or ${t.salaryMax} >= 0)
				and (${t.salaryMin} is null or ${t.salaryMax} is null or ${t.salaryMin} <= ${t.salaryMax})`
		),
		check(
			`${table}_salary_terms`,
			sql`(${t.salaryMin} is null and ${t.salaryMax} is null)
				or (${t.salaryCurrency} is not null and ${t.salaryPeriod} is not null and ${t.salaryTaxBase} is not null)`
		),
		check(`${table}_salary_currency_format`, sql`${t.salaryCurrency} ~ '^[A-Z]{3}$'`),
		check(`${table}_salary_period_values`, oneOf(t.salaryPeriod, SALARY_PERIODS)),
		check(`${table}_salary_tax_base_values`, oneOf(t.salaryTaxBase, SALARY_TAX_BASES))
	];
}

/** SQL condition «full range with a known tax base»: both bounds and a tax base other than `unknown`. */
export function fullSalary(t: SalaryColumns): SQL {
	return sql`${t.salaryMin} is not null and ${t.salaryMax} is not null and ${t.salaryTaxBase} in ('gross', 'net')`;
}

/** Salary descriptor without bounds (market indicators, external references): currency, period and tax base. */
export const salaryUnitColumns = () => ({
	currency: text().notNull(),
	period: text({ enum: SALARY_PERIODS }).notNull(),
	taxBase: text({ enum: SALARY_TAX_BASES }).notNull()
});

export function salaryUnitChecks(
	table: string,
	t: { currency: AnyPgColumn; period: AnyPgColumn; taxBase: AnyPgColumn }
) {
	return [
		check(`${table}_currency_format`, sql`${t.currency} ~ '^[A-Z]{3}$'`),
		check(`${table}_period_values`, oneOf(t.period, SALARY_PERIODS)),
		check(`${table}_tax_base_values`, oneOf(t.taxBase, SALARY_TAX_BASES))
	];
}

/** `hash` — SHA-256 in lowercase hex. */
export function sha256Check(table: string, columnName: string, column: AnyPgColumn) {
	return check(`${table}_${columnName}_format`, sql`${column} ~ '^[0-9a-f]{64}$'`);
}
